{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "First, the comptroller's office would review the foundational literacy skills plans that are sent to the Department of Education for approval. The review would check that the plans meet the requirements of subsection (f) of the same section and the rules set by the State Board of Education.",
      "rationale": "Conveys the responsible office, plans subject to review, and both compliance standards."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The comptroller or a designee would also look at whether the department first approved or denied each plan. They would look at what kinds of revisions or amendments the department required before approval.",
      "rationale": "Includes the comptroller or designee, initial approval or denial, and the nature of department-required changes for approval."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The comptroller would put these findings in the report required by § 49-1-910.",
      "rationale": "Explicitly includes the literacy-plan findings in the specified report."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Second, the bill would replace § 49-1-910 entirely. The comptroller's office would review data, practices, and outcomes related to this part of the code.",
      "rationale": "Identifies the replaced section and conveys the actor, review obligation, and scope."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The Department of Education would have to give the comptroller's office any information it requests as soon as practicable.",
      "rationale": "Includes the department's duty to provide all requested information to the comptroller's office and the required timing."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Every three years, the comptroller would submit a report on the findings to the chair of the Senate education committee, the chair of the House committee that handles student literacy, and the State Board of Education. The comptroller would also publish the report on its website.",
      "rationale": "Includes the reporting interval, findings, all required recipients, and website publication."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "rationale": "Accurately conveys the effective date."
    }
  ]
}
